flowchart TD
  A[Start from access pattern] --> B{Append only ordered by time}
  B -->|Yes| C[Time series engine]
  B -->|No| D{Query is text relevance or facets}
  D -->|Yes| E[Search index]
  D -->|No| F{Query traverses relationships}
  F -->|Yes| G[Graph store]
  F -->|No| H{Scan billions for aggregates}
  H -->|Yes| I[Columnar OLAP]
  H -->|No| J[Similarity over embeddings]
  J -->|Yes| K[Vector index]
  J -->|No| L[Stay on relational or document]

# TIME-SERIES: measurement + tags (indexed) + fields (not indexed) + time
# WHY: tags become the series key. Keep cardinality low.
# TRADE-OFF: querying by a field without tag is a full scan.
point = {
    "measurement": "api_latency",
    "tags": {"service": "checkout", "az": "us-east-1a"},  # indexed, low cardinality
    "fields": {"p99_ms": 212.0, "count": 1403},              # values, not indexed
    "time": 1757200000000000000
}
# Retention + rollup are part of the schema, not an afterthought:
# raw 7d -> 1m rollup 90d -> 1h rollup 1y

# SEARCH: analyzer choice IS the schema.
# WHY: standard analyzer lowercases + stems; keyword preserves exact IDs.
# TRADE-OFF: wrong analyzer = unsearchable data with no error.
index_mapping = {
    "mappings": {
        "properties": {
            "title": {"type": "text", "analyzer": "standard"},
            "sku": {"type": "keyword"},  # exact filter, not analyzed
            "price": {"type": "scaled_float", "scaling_factor": 100}
        }
    }
}
